import * as M from './model.js';
const $=id=>document.getElementById(id),icon=n=>`<i data-lucide="${n}"></i>`,fmt=n=>Math.floor(n||0).toLocaleString('en-US');
export const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,attrs='',gold=true)=>`<button class="btn ${gold?'btn-gold':''}" data-v2="${action}" ${attrs}>${label}</button>`;
const remaining=t=>`<span data-until="${t}">${Math.max(0,Math.ceil((t-Date.now())/1000))}s</span>`;
export class Features{
 constructor(bridge){this.b=bridge;this.api=bridge.api;this.poll=null;
  for(const [id,method]of [['gems-button','shop'],['heroes-button','heroes'],['research-button','research'],['spells-button','spells'],['clans-button','social']])$(id).addEventListener('click',()=>this[method]());
  const fullscreen=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();try{await screen.orientation?.lock?.('landscape');}catch{} }catch{bridge.toast('ဖုန်းကို ဘေးတိုက်လှည့်ပြီး Auto-rotate ဖွင့်ပါ။');}};
  $('fullscreen-button').addEventListener('click',fullscreen);$('landscape-start').addEventListener('click',fullscreen);
  document.addEventListener('submit',e=>{if(e.target.closest('#modal'))e.preventDefault();});
  document.addEventListener('click',e=>{const el=e.target.closest('[data-v2]');if(el&&!el.disabled)this.handle(el).catch(e=>bridge.toast(e.message,true));});
 }
 state(){return this.b.state();}
 show(kind,title,body,eyebrow='YOUR KINGDOM GROWS'){this.featureSignature=this.signature(kind);this.b.showModal(kind,this.b.header(eyebrow,title)+`<div class="modal-body">${body}</div>`);}
 signature(kind){const s=this.state();return JSON.stringify(kind==='heroes'?s.heroes:kind==='research'?[s.research,s.researchQueue]:kind==='spells'?[s.spells,s.spellQueue]:null);}
 tick(kind){for(const el of document.querySelectorAll('[data-until]'))el.textContent=Math.max(0,Math.ceil((Number(el.dataset.until)-Date.now())/1000))+'s';if(['heroes','research','spells'].includes(kind)&&this.signature(kind)!==this.featureSignature)this.refresh(kind);}
 refresh(kind){if(['heroes','research','spells','shop','account'].includes(kind))this[kind]();}
 heroes(){const s=this.state();this.show('heroes','Heroes of Emberfall',`<p class="modal-intro">Heroes return after battle. Upgrade them with dark elixir and use one special ability per raid.</p><div class="card-grid">${Object.entries(M.HEROES).map(([k,d])=>{const h=s.heroes[k],cost=M.heroCost(h),locked=M.hallLevel(s)<d.unlock||!s.buildings.some(b=>b.type==='altar'&&!b.finishAt);return `<article class="shop-card"><span class="card-icon">${icon(d.icon)}</span><h3>${d.name}</h3><span class="card-meta">Level ${h.level} / ${Math.min(50,M.hallLevel(s)*5)}</span><p>${d.desc}</p><p>${h.finishAt?'Upgrading · '+remaining(h.finishAt):h.recoverAt>Date.now()?'Recovering · '+remaining(h.recoverAt):h.level?'Ready for battle':'Not yet unlocked'}</p>${h.finishAt?button(`${icon('gem')}${M.skipCost(h.finishAt)} · Finish`,'skip',`data-kind="hero" data-id="${k}"`):button(locked?'Town Hall '+d.unlock+' + Hero Hall':`${icon('fuel')}${cost.dark} · ${h.level?'Upgrade':'Unlock'}`,'hero-upgrade',`data-id="${k}" ${locked||h.recoverAt>Date.now()?'disabled':''}`)}</article>`;}).join('')}</div><p class="guide-foot">Hero upgrades require their own timer. A hero under upgrade or recovering cannot deploy.</p>`);}
 research(){const s=this.state(),lab=s.buildings.find(b=>b.type==='laboratory');this.show('research','Laboratory research',`<p class="modal-intro">Research permanently raises troop hit points and damage. Upgrade your Laboratory to increase research limits.</p>${s.researchQueue.length?`<div class="training-queue">Researching ${M.TROOPS[s.researchQueue[0].type].name} · ${remaining(s.researchQueue[0].finishAt)} ${button(icon('gem')+' '+M.skipCost(s.researchQueue[0].finishAt)+' · Finish','skip','data-kind="research"')}</div>`:''}<div class="card-grid">${Object.entries(M.TROOPS).map(([k,d])=>{const l=s.research[k]||1;return `<article class="shop-card"><span class="card-icon">${icon(d.icon)}</span><h3>${d.name}</h3><p>Level ${l} → ${l+1}<br>+18% base damage and hit points</p>${button(`${icon('droplets')}${fmt(250*l*l)} · Research`,'research',`data-id="${k}" ${!lab||lab.finishAt||s.researchQueue.length||!M.troopUnlocked(s,k)?'disabled':''}`)}</article>`;}).join('')}</div>${!lab?'<p class="guide-foot">Build a Laboratory at Town Hall level 2 to begin.</p>':''}`);}
 spells(){const s=this.state(),forge=s.buildings.find(b=>b.type==='forge'&&!b.finishAt);this.show('spells','Spell Forge',`<p class="modal-intro">Prepare up to 12 spells. Each cast is consumed in battle.</p><div class="card-grid">${Object.entries(M.SPELLS).map(([k,d])=>`<article class="shop-card"><span class="card-icon purple">${icon(d.icon)}</span><h3>${d.name}</h3><span class="card-meta">${s.spells[k]||0} ready</span><p>${d.desc}</p>${button(`${icon('droplets')}${d.cost} · Brew`,'brew',`data-id="${k}" ${!forge||forge.level<d.unlock?'disabled':''}`)}</article>`).join('')}</div><div class="training-queue">${s.spellQueue.length?s.spellQueue.map(q=>`${M.SPELLS[q.type].name} · ${remaining(q.finishAt)}`).join(' / '):'The forge is ready.'}</div>${!forge?'<p class="guide-foot">Build a Spell Forge at Town Hall level 2 to begin brewing.</p>':''}`);}
 shop(){const s=this.b.root?.()||this.state(),enabled=this.api.online&&this.api.config.payments,packs=this.api.config.packs?.length?this.api.config.packs:M.GEM_PACKS;this.show('shop','The Gem Treasury',`<p class="wallet-total">${icon('gem')} ${fmt(s.gems)} <span>gems</span></p><p class="modal-intro">Clear trees and rocks for a chance to find 1–6 gems. Every obstacle has a 42% chance to drop gems; the result is decided when clearing begins.</p><div class="card-grid">${packs.map(p=>`<article class="shop-card"><span class="card-icon gem-icon">${icon('gem')}</span><h3>${p.name}</h3><div class="pack-quantity">${fmt(p.gems)}</div><p>One-time purchase${this.api.config.paymentTest?' · Test checkout':''}</p>${button('$'+(p.cents/100).toFixed(2)+' USD · Buy','buy',`data-id="${p.id}" ${!enabled?'disabled':''}`)}</article>`).join('')}</div>${!enabled?'<p class="shop-status">Gem purchases are not available yet. Earn gems by clearing obstacles.</p>':!this.api.user?.registered?'<p class="shop-status">Create an account before buying gems so you can return to your village.</p>':''}<div class="treasury-uses"><h3>Spend your gems</h3><div class="panel-actions">${button(`${icon('hammer')}Builder ${s.builders+1} · ${[0,0,250,500,1000][s.builders]||1000} gems`,'builder',s.builders>=5?'disabled':'')}${button(`${icon('coins')}1,500 gold · 20 gems`,'exchange','data-resource="gold"')}${button(`${icon('droplets')}1,500 elixir · 20 gems`,'exchange','data-resource="elixir"')}${button(`${icon('fuel')}200 dark · 20 gems`,'exchange','data-resource="dark"')}</div></div><p class="guide-foot">Gem purchase prices are configured by the server owner. Gems also finish construction, research, hero upgrades, and training timers.</p>`,'GEMS · BUILDERS · RESOURCES');}
 account(){const u=this.api.user;this.show('account','Your village account',!this.api.online?'<p class="modal-intro">This standalone copy saves on your device. Run the included server to enable accounts and shared villages.</p>':`<p class="modal-intro">${u?.registered?'Signed in as '+escapeHtml(u.name):'Create an account to keep this village and access it from another device.'}</p>${u?.registered?`<form id="password-form"><label>Current password<input id="current-password" type="password" autocomplete="current-password" maxlength="128"></label><label>New password<input id="new-password" type="password" autocomplete="new-password" minlength="10" maxlength="128"></label><p class="guide-foot">Changing your password signs out every other session.</p>${button('Change password','change-password','type="button"')}${button('Sign out','logout','type="button"',false)}</form>`:`<form id="account-form"><label>Username<input id="account-name" name="username" autocomplete="username" minlength="3" maxlength="24" required></label><label>Password<input id="account-password" name="password" type="password" autocomplete="current-password" minlength="10" maxlength="128" required></label><div class="panel-actions">${button('Save this village','register','type="button"')}${button('Sign in to existing village','login','type="button"',false)}</div></form>`}<p class="guide-foot">Accounts use a username and password. Keep your password safe; email password recovery is not included.</p>`);}
 async social(){if(!this.api.online){this.show('social','Clans & Rivals','<p class="modal-intro">Clans, shared leaderboards, and player raids work when the included server is running.</p>');return;}const data=await this.api.request('/clans'),players=await this.api.request('/players');this.socialData=data;this.show('social','Clans & Rivals',`<div class="social-toolbar">${button(icon('user')+' '+escapeHtml(this.api.user?.name),'account','',false)}${button(icon('history')+' Battle log','raids','',false)}${button(icon('refresh-cw')+' Refresh','social','',false)}</div>${data.clanId?`<h3>${escapeHtml(data.clans.find(c=>c.id===data.clanId)?.name)}</h3><div class="clan-members">${data.members.map(p=>`<div class="enemy-row"><div class="enemy-data"><strong>${escapeHtml(p.name)}</strong><small>${p.glory} glory</small></div>${p.id!==this.api.user.id?button('Donate Guardian','donate',`data-id="${p.id}"`):''}</div>`).join('')}</div><div class="clan-chat">${data.messages.map(m=>`<p><strong>${escapeHtml(m.name)}</strong> ${escapeHtml(m.message)}</p>`).join('')||'<p>No messages yet. Welcome to your clan.</p>'}</div><form class="chat-form"><input id="clan-message" maxlength="280" placeholder="Message your clan" aria-label="Clan message">${button('Send','chat','type="button"')}</form>${button('Leave clan','leave','',false)}`:`<form class="chat-form"><input id="clan-name" maxlength="24" placeholder="Your clan name" aria-label="Clan name">${button('Create clan','clan-create','type="button"')}</form><div class="enemy-list">${data.clans.map(c=>`<div class="enemy-row"><div class="enemy-data"><strong>${escapeHtml(c.name)}</strong><small>${c.members}/30 members · ${c.glory} glory</small></div>${button('Join','join',`data-id="${c.id}"`)}</div>`).join('')||'<p class="modal-intro">No clans yet. Create the first one.</p>'}</div>`}<h3>Rival villages</h3><p class="modal-intro">Raid another player’s saved defenses. Damaged buildings recover after the raid; defenders receive a five-minute shield.</p><div class="enemy-list">${players.players.map(p=>`<div class="enemy-row"><div class="enemy-data"><strong>${escapeHtml(p.name)}</strong><small>Town Hall ${p.hall} · ${p.glory} glory</small></div>${button(p.shield?'Shielded':'Scout','pvp',`data-id="${p.id}" ${p.shield||p.clanId&&p.clanId===data.clanId?'disabled':''}`)}</div>`).join('')||'<p class="modal-intro">Another player needs to join this server before rivals appear.</p>'}</div>`);}
 async raids(){const data=await this.api.request('/raids');this.show('raids','Battle history',`<div class="enemy-list">${data.raids.map(r=>`<div class="enemy-row"><div class="enemy-data"><strong>${r.attacker_id===this.api.user.id?'Your attack':'Defense against '+escapeHtml(r.attacker)}</strong><small>${r.result.percent}% destruction · ${'★'.repeat(r.result.stars)} · ${new Date(r.created_at).toLocaleString()}</small></div><span>${fmt(r.result.gold)} gold</span></div>`).join('')||'<p class="modal-intro">Your raid history will appear here.</p>'}</div>`);}
 obstacle(id){const o=this.state().obstacles.find(o=>o.id===id);if(!o)return;this.show('obstacle',o.type==='tree'?'Clear this tree':'Clear these rocks',`<p class="modal-intro">Free up building space. Clearing has a 42% chance to reward 1–6 gems.</p>${o.finishAt?`<p>Builder at work · ${remaining(o.finishAt)}</p>${button(icon('gem')+' '+M.skipCost(o.finishAt)+' · Finish','skip',`data-kind="obstacle" data-id="${o.id}"`)}`:button(`${icon('axe')}Clear · ${o.type==='tree'?75:120} gold · ${o.type==='tree'?8:12}s`,'clear',`data-id="${o.id}"`)}`);}
 enhanceBuilding(b){const panel=$('building-panel');const targets={altar:['crown','Manage heroes','heroes'],laboratory:['microscope','Research troops','research'],forge:['wand-sparkles','Brew spells','spells'],cottage:['hammer','Hire a builder','shop']};if(targets[b.type]){const [i,label,action]=targets[b.type];panel.insertAdjacentHTML('beforeend',button(icon(i)+' '+label,action,'style="width:100%;margin-top:10px"'));}if(b.finishAt)panel.insertAdjacentHTML('beforeend',button(`${icon('gem')}${M.skipCost(b.finishAt)} gems · Finish now`,'skip',`data-kind="building" data-id="${b.id}" style="width:100%;margin-top:10px"`));}
 battleSpells(){const b=this.b.battle();if(!b)return;this.show('battle-spells','Choose a spell',`<div class="card-grid">${Object.entries(M.SPELLS).map(([k,d])=>`<article class="shop-card"><span class="card-icon purple">${icon(d.icon)}</span><h3>${d.name}</h3><p>${d.desc}</p>${button((b.spellStock[k]||0)+' ready · Select','select-spell',`data-id="${k}" ${!(b.spellStock[k]>0)?'disabled':''}`)}</article>`).join('')}</div>`);}
 heroCards(b,selected){return Object.entries(M.HEROES).filter(([k])=>b.heroStock?.[k]||b.units.some(u=>u.hero&&u.type===k)).map(([k,d])=>{const unit=b.units.find(u=>u.hero&&u.type===k);return `<button class="deploy-card ${selected===k?'selected':''}" data-v2="${unit?'ability':'select-hero'}" data-id="${k}" ${unit&&(unit.hp<=0||unit.abilityUsed)?'disabled':''}><b>${unit?'★':b.heroStock[k]}</b>${icon(d.icon)}<span>${unit?'Ability':d.name}</span></button>`;}).join('');}
 async handle(el){const action=el.dataset.v2,b=this.b;el.disabled=true;try{
  if(['heroes','research','spells','shop','account','social','raids'].includes(action)&&!el.dataset.id){await this[action]();return;}
  if(action==='select-hero'){b.selectHero(el.dataset.id);return;}
  if(action==='select-spell'){b.selectSpell(el.dataset.id);return;}
  if(action==='ability'){await b.mutate({type:'battle-ability',hero:el.dataset.id,battleId:b.battle()?.id});return;}
  if(action==='buy'){if(!this.api.user?.registered){this.account();return;}const r=await this.api.request('/payments/checkout',{method:'POST',data:{pack:el.dataset.id}});location.assign(r.url);return;}
  if(action==='register'||action==='login'){const r=await this.api.request('/auth/'+action,{method:'POST',data:{username:$('account-name').value,password:$('account-password').value}});if(r.state)b.apply(r);b.toast(action==='register'?'Your village account is ready.':'Welcome back.');this.account();return;}
  if(action==='change-password'){await this.api.request('/auth/password',{method:'POST',data:{currentPassword:$('current-password').value,newPassword:$('new-password').value}});b.toast('Password changed. Other sessions are signed out.');this.account();return;}
  if(action==='logout'){await this.api.request('/auth/logout',{method:'POST',data:{}});location.reload();return;}
  if(action==='pvp'){await b.startBattle(0,el.dataset.id);return;}
  if(['clan-create','join','leave','chat','donate'].includes(action)){await this.api.request('/clans',{method:'POST',data:{action:action==='clan-create'?'create':action,name:$('clan-name')?.value,id:el.dataset.id,message:$('clan-message')?.value,troop:'guardian'}});await b.sync();await this.social();return;}
  const map={'hero-upgrade':{type:action,hero:el.dataset.id},research:{type:action,troop:el.dataset.id},brew:{type:action,spell:el.dataset.id},clear:{type:action,id:el.dataset.id},skip:{type:action,kind:el.dataset.kind,id:el.dataset.id},builder:{type:action,realm:'home'},exchange:{type:action,realm:'home',resource:el.dataset.resource}};
  if(map[action]){await b.mutate(map[action]);b.toast(action==='clear'?'Your builder is clearing the obstacle.':action==='skip'?'Finished.':action==='builder'?'A new builder joined the village.':'Done.');if(action==='clear'||action==='skip')b.closeModal();else this.refresh(b.modalKind());}
 }finally{if(el.isConnected)el.disabled=false;}}
}
